const order=[];for(let start=0;start<ranked.length;start+=10){const pool=ranked.slice(start,start+10);while(pool.length){const prev=order.length?M.motifs[order[order.length-1]]:null;let pick=pool.findIndex(e=>!prev||M.motifs[e.index].kind!==prev.kind);if(pick<0)pick=0;order.push(pool.splice(pick,1)[0].index);}}
