const thresholds=limits.slice(0,3).map(n=>ranked[n-1].score);
function classify(features){const s=thresholds.findIndex(t=>features.score<=t);const stage=stages[s<0?3:s].id;return stage==='arrive'&&features.anchors?'discover':stage;}
